#!/usr/bin/env python3

import os

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_DIR = os.path.join(BASE_DIR, "data")

INPUT_FILE = os.path.join(BASE_DIR, "src", "INPUT.DAT")
ACCOUNTS_FILE = os.path.join(DATA_DIR, "ACCOUNTS.DAT")
BOOKS_FILE = os.path.join(DATA_DIR, "BOOKS.DAT")
TRANSACTIONS_FILE = os.path.join(DATA_DIR, "TRANSACTIONS.DAT")

ACCOUNT_RECORD_SIZE = 34
BOOK_RECORD_SIZE = 28
TRANSACTION_RECORD_SIZE = 22
INPUT_RECORD_SIZE = 22

MAX_BALANCE = 10 ** 10


def read_records(path, record_size):
    with open(path, "rb") as f:
        data = f.read()

    records = []
    for offset in range(0, len(data), record_size):
        record = data[offset:offset + record_size]
        if len(record) < record_size:
            record = record.ljust(record_size, b"\x00")
        records.append(record)
    return records


def write_records(path, records):
    with open(path, "wb") as f:
        for record in records:
            f.write(record)


def display_numeric(raw):
    value = 0
    for byte in raw:
        if 48 <= byte <= 57:
            digit = byte - 48
        else:
            digit = 0
        value = value * 10 + digit
    return value


def numeric_text(value):
    return ("%010d" % (value % MAX_BALANCE)).encode("ascii")


def update_balance(balance, amount, add):
    if add:
        result = balance + amount
    else:
        result = balance - amount

    if result < 0:
        result = -result
    return result % MAX_BALANCE


def main():
    with open(INPUT_FILE, "rb") as f:
        input_record = f.read(INPUT_RECORD_SIZE)

    if not input_record:
        print("Error: Input file is empty")
        return

    if len(input_record) < INPUT_RECORD_SIZE:
        input_record = input_record.ljust(INPUT_RECORD_SIZE, b"\x00")

    buyer_id = input_record[0:4]
    seller_id = input_record[4:8]
    book_id = input_record[8:12]
    amount_raw = input_record[12:22]
    amount = display_numeric(amount_raw)
    amount_text = numeric_text(amount)

    accounts = read_records(ACCOUNTS_FILE, ACCOUNT_RECORD_SIZE)

    buyer_found = False
    seller_found = False
    for record in accounts:
        account_id = record[0:4]
        if account_id == buyer_id:
            buyer_found = True
        if account_id == seller_id:
            seller_found = True

    books = read_records(BOOKS_FILE, BOOK_RECORD_SIZE)

    book_found = False
    valid_owner = False
    for record in books:
        if record[0:4] == book_id:
            book_found = True
            if record[24:28] == seller_id:
                valid_owner = True

    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    for index, record in enumerate(accounts):
        account_id = record[0:4]
        balance = display_numeric(record[24:34])
        changed = False

        if account_id == buyer_id:
            balance = update_balance(balance, amount, False)
            changed = True
        if account_id == seller_id:
            balance = update_balance(balance, amount, True)
            changed = True

        if changed:
            accounts[index] = record[:24] + numeric_text(balance) + record[34:]

    write_records(ACCOUNTS_FILE, accounts)

    for index, record in enumerate(books):
        if record[0:4] == book_id:
            books[index] = record[:24] + buyer_id + record[28:]

    write_records(BOOKS_FILE, books)

    transaction = book_id + amount_text + seller_id + buyer_id
    with open(TRANSACTIONS_FILE, "ab") as f:
        f.write(transaction)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()

